/* navigation buttons in context menu */
#context-navigation,
#mailContext-navigation {
  --indicator-background: transparent;

  & > .menuitem-iconic {
    flex: 1;
    justify-content: center;
    align-items: center;
    margin: var(--menu-item-margin);
    padding: 0;
    border-radius: var(--button-border-radius);

    &[_moz-menuactive] {
      /* Override the menu-shared.css rule. */
      &[disabled] {
        background-color: transparent;
      }

      &:not([disabled]) {
        color: inherit;
        background-color: var(--panel-background-color-dimmed);
      }
    }

    & > .menu-icon {
      appearance: none;
      padding: 0;
      margin: 7px;
      -moz-context-properties: fill, stroke;
      stroke: currentColor;

      &::after {
        content: "";
        box-sizing: border-box;
        background-color: var(--indicator-background);
        border-radius: 4px;
        inline-size: 12px;
        block-size: 4px;
        margin-block: -6px 1px;
      }
    }

